from pathlib import Path
p=Path('design/extraction-blue-v2')
paths={
'link':'<path d="M10,7 L12,5 A4.95,4.95 0,0 1,19 12 L17,14 M14,17 L12,19 A4.95,4.95 0,0 1,5 12 L7,10 M8.5,15.5 L15.5,8.5"/>',
'open':'<path d="M14 3h7v7m0-7L10 14M10 4H5a2 2 0 0 0-2 2v13a2 2 0 0 0 2 2h13a2 2 0 0 0 2-2v-5"/>',
'scan':'<path d="M3 8V4a1 1 0 0 1 1-1h4m8 0h4a1 1 0 0 1 1 1v4m0 8v4a1 1 0 0 1-1 1h-4M8 21H4a1 1 0 0 1-1-1v-4M6 12h12"/>',
'globe':'<circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M5 6.5h14M5 17.5h14"/>',
'download':'<path d="M12 3v12m-5-5 5 5 5-5M4 15v5a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-5"/>',
'select':'<path d="M11 4H5a1 1 0 0 0-1 1v14a1 1 0 0 0 1 1h14a1 1 0 0 0 1-1v-6M10 11l3 3 8-9"/>',
'history':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',
'chevron':'<path d="m6 9 6 6 6-6"/>',
'back':'<path d="m15 5-7 7 7 7"/>',
'up':'<path d="M12 20V4m-6 6 6-6 6 6"/>',
'pause':'<path d="M8 5v14M16 5v14"/>',
'play':'<path d="m8 4 12 8-12 8Z"/>',
'paste':'<rect x="6" y="5" width="14" height="16" rx="2"/><rect x="9" y="2" width="8" height="5" rx="1.5"/>',
'copy':'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 4V3H3v13h1"/>',
'check':'<path d="m5 12 4 4L19 6"/>',
'info':'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>'}
# Eight dots keep the spinner sharp at a small size.
import math
paths['spinner']=''.join(f'<circle cx="{12+8*math.cos(i*math.pi/4):.3f}" cy="{12+8*math.sin(i*math.pi/4):.3f}" r="1.5" fill="currentColor" stroke="none" opacity="{.18+i*.11:.2f}"/>' for i in range(8))
for name,path in paths.items():
 (p/'assets'/f'{name}.svg').write_text(f'<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{path}</svg>',encoding='utf8')
def ico(name,cls=''):return f'<svg class="{cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round">{paths[name]}</svg>'
def sticker(n):
 rabbit=n%2==0
 ears='<path d="M34 48V20q0-13 9-13t9 13v25M67 45V20q0-13 9-13t9 13v28" fill="#fff"/><path d="M41 19v21m35-21v21" stroke="#ffa5ba" stroke-width="5"/>' if rabbit else '<path d="m21 48 1-30 23 15m27 0 24-15 1 31" fill="#eeeef5"/>'
 face=f'<ellipse cx="60" cy="69" rx="43" ry="35" fill="{"#fff" if rabbit else "#eeeef5"}"/>'
 eyes='<path d="m34 63 8-4 8 4m20 0 8-4 8 4"/>' if n%3==0 else '<circle cx="41" cy="63" r="3" fill="#172238"/><circle cx="79" cy="63" r="3" fill="#172238"/>'
 mouth='<path d="M48 76q12 24 24 0Z" fill="#ffb4c5"/>' if n%3!=1 else '<path d="M49 78q11 9 22 0"/>'
 return f'<svg class="sticker" viewBox="0 0 120 120" fill="none" stroke="#172238" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round">{ears}{face}{eyes}{mouth}<ellipse cx="30" cy="76" rx="7" ry="3" fill="#ffc4d3" stroke="none"/><ellipse cx="90" cy="76" rx="7" ry="3" fill="#ffc4d3" stroke="none"/></svg>'
def grid():
 return '<div class="grid">'+''.join(f'<button class="tile" aria-label="选择示例素材{n+1}">{sticker(n)}'+('<span class="badge">GIF</span>' if n in [1,3] else f'<span class="video">{ico("play")}</span>' if n==5 else '')+'<span class="tick">'+ico('check')+'</span></button>' for n in range(6))+'</div>'
def phone(state='scan',dark=False):
 count=0 if state=='empty' else 24
 status=f'<div class="idle">{ico("info")}<span>粘贴作品链接，打开网页后进入评论区</span></div>' if state=='empty' else f'<div class="scan-card"><div class="scan-top">{ico("spinner","spinner")}<div><b>扫描中</b><p>主评论 128 · 回复 36</p><p>已找到 24 个素材</p></div></div><div class="progress"><i></i></div><button class="detail">查看明细 {ico("chevron")}</button></div>' if state=='scan' else f'<div class="idle complete">{ico("check")}<span>扫描完成 · 共找到 24 个素材</span></div>'
 return f'''<div class="phone {'dark' if dark else ''}" data-state="{state}"><div class="statusbar"><b>10:24</b><span>◢ ▰ 100%</span></div><header><button class="icon-button">{ico('back')}</button><b>抖音提取</b><button class="record">{ico('history')}记录</button></header><main><div class="url"><span class="link-icon">{ico('link')}</span><span class="url-text">{'粘贴作品链接或分享文案' if state=='empty' else 'v.douyin.com/xTsI21l65yg/'}</span><button class="mini" title="粘贴">{ico('paste')}</button><button class="mini" title="复制">{ico('copy')}</button></div><div class="primary-actions"><button class="outline">{ico('open')}打开作品</button><button class="primary scan-action">{ico('pause' if state=='scan' else 'scan')}{'暂停扫描' if state=='scan' else '扫描评论'}</button></div>{status}<button class="web">{ico('globe')}<b>网页操作</b>{ico('chevron','fold')}</button><div class="web-preview">网页交互区域 · 布局示例</div><div class="result-title"><b>提取结果</b><button class="multi">{ico('select')}多选</button></div><div class="filter"><div class="indicator"></div><button class="active" data-filter="0">全部 {count}</button><button data-filter="1">动图</button><button data-filter="2">图片</button></div><div class="results">{('<div class="empty"><span>'+ico('scan')+'</span><b>等待提取素材</b><p>打开作品并扫描评论后<br>图片与动态素材会展示在这里</p></div>') if state=='empty' else grid()}</div></main><button class="top">{ico('up')}置顶</button><footer><div><b>已提取 {count} 个</b><small>{'保存到 下载 / DouYinGetting' if state=='empty' else '图片与动态素材可直接预览'}</small></div><button class="save">{ico('download')}保存全部</button></footer><div class="gesture"><i></i></div><div class="toast"></div></div>'''
css=''':root{--bg:#f4f6fa;--surface:#fff;--ink:#0f172a;--muted:#536176;--line:#dce2ed;--blue:#456bff;--soft:#e7edff;--track:#e9edf4}@font-face{font-family:Noto;src:url('../home-blue-v2/assets/NotoSansSC.ttf');font-weight:100 900}*{box-sizing:border-box}body{margin:0;background:#e9edf5;color:#0f172a;font-family:Noto,sans-serif}button{font:inherit;cursor:pointer;display:flex;align-items:center;justify-content:center;gap:7px;transition:transform 120ms ease,background 160ms ease;touch-action:manipulation}button:active{transform:scale(.96)}svg{width:20px;height:20px;flex-shrink:0}button{border:0;background:none;color:inherit;padding:0}.board{padding:28px 32px;width:1282px}.board>h1{font-size:25px;font-weight:800;margin:0 0 5px}.sub{font-size:12px;color:#68758c;margin-bottom:20px}.phones{display:flex;gap:24px}.phone-wrap>h3{font-size:13px;color:#536176;margin:0 0 10px}.phone{--bg:#f4f6fa;--surface:#fff;--ink:#0f172a;--muted:#536176;--line:#dce2ed;--blue:#456bff;--soft:#e7edff;--track:#e9edf4;width:390px;height:844px;background:var(--bg);color:var(--ink);position:relative;overflow:hidden;border-radius:22px;box-shadow:0 8px 26px #1c2b4a0d;font-size:13px}.phone.dark{--bg:#0d1320;--surface:#1a2436;--ink:#f3f6ff;--muted:#bec9dc;--line:#303e55;--blue:#708cff;--soft:#24345c;--track:#222e42}.statusbar{height:32px;display:flex;justify-content:space-between;padding:8px 19px 0;font-size:12px}.statusbar span{font-size:10px}header{height:54px;display:flex;align-items:center;padding:0 16px;position:relative;justify-content:space-between}header>b{font-size:18px;font-weight:750;position:absolute;left:50%;transform:translateX(-50%);pointer-events:none}.icon-button{width:40px;height:44px}.record{font-size:12px;font-weight:650;height:36px;gap:4px}.record svg{width:17px;height:17px}main{padding:10px 16px 80px;height:662px;overflow:auto;scrollbar-width:none}.url{display:flex;align-items:center;height:46px;padding:0 7px 0 12px;gap:8px;border:1px solid var(--line);border-radius:12px;background:var(--surface)}.link-icon{color:var(--blue);display:flex}.link-icon svg{width:19px;height:19px}.url-text{overflow:hidden;white-space:nowrap;text-overflow:ellipsis;flex:1;font-size:12px;font-weight:450;color:var(--muted)}.mini{width:32px;height:40px;color:var(--blue)}.mini svg{width:18px;height:18px}.primary-actions{display:flex;gap:10px;margin:12px 0 16px}.primary-actions button{height:44px;flex:1;border-radius:12px;font-size:14px;font-weight:700}.outline{border:1px solid var(--blue);background:var(--surface);color:var(--blue)}.primary{background:var(--blue);color:#fff}.idle{display:flex;align-items:center;gap:9px;background:var(--surface);border:1px solid var(--line);border-radius:14px;padding:12px;font-size:12px;line-height:20px;margin-bottom:12px}.idle>svg{color:var(--blue);width:18px;height:18px}.complete{color:var(--muted)}.scan-card{padding:16px;border:1px solid var(--line);border-radius:14px;background:var(--surface);margin-bottom:12px}.scan-top{display:flex;gap:12px}.scan-top>svg{width:24px;height:24px;color:var(--blue);margin-top:1px}.scan-top b{font-size:16px;font-weight:750;line-height:23px}.scan-top p{font-size:12px;line-height:18px;margin:5px 0 0;color:var(--muted)}.spinner{animation:spin 1s linear infinite}.progress{height:4px;background:var(--soft);border-radius:4px;overflow:hidden;margin:14px 0 12px}.progress i{display:block;height:100%;width:35%;border-radius:4px;background:var(--blue);animation:progress 1.5s ease-in-out infinite alternate}.detail{font-weight:650;color:var(--blue);font-size:12px}.detail svg{width:15px;height:15px;transform:rotate(-90deg)}.web{height:44px;width:100%;border:1px solid var(--line);background:var(--surface);padding:0 12px;border-radius:12px;gap:9px;font-size:13px}.web b{font-weight:650;flex:1;text-align:left}.web .fold{width:18px;height:18px;transition:transform 180ms}.web.expanded .fold{transform:rotate(180deg)}.web-preview{height:0;opacity:0;overflow:hidden;text-align:center;font-size:12px;color:var(--muted);background:var(--surface);border-radius:12px;transition:height 180ms ease,opacity 180ms ease;display:grid;place-items:center}.web-preview.open{height:96px;opacity:1;margin-top:8px}.result-title{display:flex;align-items:center;justify-content:space-between;margin:22px 0 12px}.result-title>b{font-size:18px;font-weight:750;line-height:26px}.multi{height:32px;color:var(--blue);font-size:12px;font-weight:650}.multi svg{width:18px;height:18px}.filter{height:36px;display:flex;position:relative;border-radius:10px;background:var(--track);padding:3px;margin-bottom:12px}.filter button{flex:1;position:relative;z-index:1;font-size:12px;font-weight:650}.filter button.active{color:#fff}.indicator{position:absolute;top:3px;bottom:3px;left:3px;width:calc((100% - 6px)/3);border-radius:8px;background:var(--blue);transition:transform 220ms cubic-bezier(.2,.65,.3,1)}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:8px}.tile{aspect-ratio:1;border:1px solid var(--line);border-radius:12px;background:var(--surface);position:relative;overflow:hidden;transition:transform 120ms,border-color 150ms}.sticker{width:96%;height:96%}.badge{position:absolute;right:5px;top:5px;background:var(--blue);color:#fff;border-radius:5px;padding:1px 5px;font-size:9px;font-weight:700}.video{position:absolute;right:6px;bottom:6px;width:22px;height:22px;background:#172238d9;color:#fff;border-radius:50%;display:grid;place-items:center}.video svg{width:12px;height:12px;fill:#fff;stroke-width:1.2}.tick{display:none;position:absolute;right:6px;top:6px;width:22px;height:22px;border-radius:50%;background:#8d99b49c;color:#fff}.tick svg{width:15px;height:15px}.selecting .tick{display:grid;place-items:center;animation:checkin 150ms}.selecting .badge{top:auto;bottom:6px;right:auto;left:6px}.tile.checked{border:2px solid var(--blue)}.tile.checked .tick{background:var(--blue)}.multi.on{background:var(--blue);color:#fff;padding:0 10px;border-radius:8px}.results.change{animation:enter 220ms ease}.empty{padding:26px 14px;background:var(--surface);border:1px dashed var(--line);border-radius:14px;text-align:center;color:var(--muted);display:flex;flex-direction:column;align-items:center;gap:8px}.empty>span{display:grid;place-items:center;width:40px;height:40px;background:var(--soft);color:var(--blue);border-radius:12px}.empty b{font-size:13px;font-weight:650;color:var(--ink)}.empty p{font-size:12px;line-height:20px;margin:0}.top{position:absolute;right:16px;bottom:104px;border:1px solid var(--line);background:var(--surface);border-radius:18px;height:36px;padding:0 12px;color:var(--blue);font-size:12px;font-weight:650;box-shadow:0 4px 12px #1425470d}.top svg{width:16px;height:16px}footer{position:absolute;bottom:24px;left:0;right:0;height:64px;display:flex;justify-content:space-between;align-items:center;padding:0 16px;border-top:1px solid var(--line);background:var(--surface)}footer b{font-size:14px;font-weight:750}footer small{display:block;font-size:10px;line-height:18px;color:var(--muted)}.save{height:40px;padding:0 14px;border-radius:11px;background:var(--blue);color:#fff;font-size:13px;font-weight:700;gap:7px}.save svg{width:18px;height:18px}.save.saving svg{animation:download 420ms ease}.gesture{height:24px;position:absolute;bottom:0;left:0;right:0;background:var(--surface);display:grid;place-items:center}.gesture i{width:112px;height:4px;border-radius:4px;background:var(--ink);opacity:.75}.toast{position:absolute;left:50%;bottom:104px;transform:translateX(-50%);padding:9px 14px;background:var(--ink);color:var(--surface);font-size:12px;white-space:nowrap;border-radius:10px;opacity:0;pointer-events:none;transition:opacity 150ms}.toast.visible{opacity:1}.controls{display:none;margin:20px auto;width:390px;gap:8px;flex-wrap:wrap}.controls button,.controls label{background:#fff;border:1px solid #dce2ed;border-radius:9px;padding:8px;font-size:12px}.single{background:#e9edf5}.single .board{display:none}.single .solo{display:block;margin:auto;width:390px}.solo{display:none}.interactive .controls{display:flex}.motion-off *{animation:none!important;transition:none!important}@keyframes spin{to{transform:rotate(360deg)}}@keyframes progress{from{transform:translateX(0)}to{transform:translateX(180%)}}@keyframes enter{from{opacity:.3;transform:translateX(var(--direction,9px))}to{opacity:1;transform:none}}@keyframes checkin{from{opacity:0;transform:scale(.7)}to{opacity:1;transform:scale(1)}}@keyframes download{50%{transform:translateY(3px)}}'''
js='''const q=new URLSearchParams(location.search);if(q.has('single'))document.body.classList.add('single');if(q.has('interactive'))document.body.classList.add('interactive');if(q.has('dark'))document.querySelector('.solo .phone').classList.add('dark');function toast(p,t){let v=p.querySelector('.toast');v.textContent=t;v.classList.add('visible');setTimeout(()=>v.classList.remove('visible'),1500)}document.querySelectorAll('.phone').forEach(p=>{let filter=p.querySelector('.filter'),previous=0,counts=p.dataset.state==='empty'?[0,0,0]:[24,9,15],labels=['全部','动图','图片'];filter.querySelectorAll('button').forEach((b,i)=>b.onclick=()=>{filter.querySelectorAll('button').forEach((v,j)=>{v.classList.toggle('active',i===j);v.textContent=labels[j]+(i===j?' '+counts[j]:'')});filter.querySelector('.indicator').style.transform=`translateX(${i*100}%)`;p.querySelectorAll('.tile').forEach((t,n)=>{let dynamic=[1,3,5].includes(n);t.style.display=i===0||(i===1?dynamic:!dynamic)?'':'none'});let r=p.querySelector('.results');r.style.setProperty('--direction',previous<i?'9px':'-9px');previous=i;r.classList.remove('change');void r.offsetWidth;r.classList.add('change')});p.querySelector('.multi').onclick=function(){let on=p.classList.toggle('selecting');this.classList.toggle('on',on);this.innerHTML=on?'完成':`SELECTICON多选`;p.querySelectorAll('.tile').forEach(t=>t.classList.remove('checked'))};p.querySelectorAll('.tile').forEach(t=>t.onclick=()=>{if(p.classList.contains('selecting'))t.classList.toggle('checked');else toast(p,'素材预览 · 交互演示')});p.querySelector('.web').onclick=function(){this.classList.toggle('expanded');p.querySelector('.web-preview').classList.toggle('open')};p.querySelector('.save').onclick=function(){this.classList.remove('saving');void this.offsetWidth;this.classList.add('saving');toast(p,'保存反馈 · 交互演示')};p.querySelector('.top').onclick=()=>p.querySelector('main').scrollTo({top:0,behavior:document.body.classList.contains('motion-off')?'instant':'smooth'});p.querySelectorAll('.mini').forEach(b=>b.onclick=()=>toast(p,`${b.title} · 交互演示`));p.querySelector('.outline').onclick=()=>toast(p,'打开作品 · 交互演示');p.querySelector('.scan-action').onclick=()=>toast(p,'扫描状态 · 交互演示')});document.querySelector('[data-demo=theme]').onclick=()=>document.querySelector('.solo .phone').classList.toggle('dark');document.querySelector('#motion').onchange=e=>document.body.classList.toggle('motion-off',!e.target.checked);if(q.has('test')){let p=document.querySelector('.solo .phone');p.querySelectorAll('.filter button')[1].click();let filter=p.querySelectorAll('.filter button')[1].textContent==='动图 9';p.querySelector('.multi').click();p.querySelector('.tile').click();let select=p.classList.contains('selecting')&&p.querySelector('.tile').classList.contains('checked');p.querySelector('.web').click();let web=p.querySelector('.web-preview').classList.contains('open');document.querySelector('#motion').click();let motion=document.body.classList.contains('motion-off');document.body.dataset.probe=JSON.stringify({filter,select,web,motion});}document.fonts.ready.then(()=>document.title='ready');'''.replace('SELECTICON',ico('select'))
html=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>提取页 · 组件美术稿</title><style>{css}</style><body><div class="controls"><button data-demo="theme">切换深浅色</button><label><input id="motion" type="checkbox" checked>页面动效</label><span style="font-size:11px;color:#536176">按钮可点击；所有素材和数据均为演示</span></div><div class="solo">{phone('scan')}</div><div class="board"><h1>咻咿 · 提取界面美术稿</h1><div class="sub">B / 03　图标与布局规范　·　390 × 844 基准　·　扫描数字、素材均为示例</div><div class="phones"><div class="phone-wrap"><h3>01 / 待扫描 · 紧凑链接与操作区</h3>{phone('empty')}</div><div class="phone-wrap"><h3>02 / 扫描中 · 进度与结果同屏</h3>{phone('scan')}</div><div class="phone-wrap"><h3>03 / 深色结果 · 同一套图标与层级</h3>{phone('results',True)}</div></div></div><script>{js}</script></body></html>'''
(p/'index.html').write_text(html,encoding='utf8')
(p/'preview.html').write_text(html.replace('<body>', '<body class="single interactive">'),encoding='utf8')
# Separate component sheet uses the same real SVG sources and CSS tokens.
labels={'link':'链接 / 19','open':'打开作品 / 20','scan':'扫描评论 / 20','spinner':'扫描中 / 24','globe':'网页操作 / 20','download':'保存全部 / 18','select':'多选 / 18','history':'记录 / 17','paste':'粘贴 / 18','copy':'复制 / 18','chevron':'展开 / 18','up':'置顶 / 16'}
icons=''.join(f'<div class="icon-cell">{ico(n)}<b>{t}</b></div>' for n,t in labels.items())
rows=[('顶部标题','18 / 750','保留记录入口；不增加设置'),('操作按钮','14 / 700','图标与文字间距 7；按钮高 44'),('扫描标题','16 / 750','计数 12 / 400；不显示虚假百分比'),('网页操作','13 / 650','地球图标＋普通旋转箭头'),('提取结果','18 / 750','移除重复说明，标题与多选同行'),('分类标签','12 / 650','蓝底白字；仅选中项显示数量'),('底部统计','14 / 750','次行说明 10 / 400'),('保存全部','13 / 700','下载图标＋文字；按钮高 40')]
tr=''.join(f'<tr><td>{a}</td><td>{b}</td><td>{c}</td></tr>' for a,b,c in rows)
comp=f'''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><title>图标与样式规范</title><style>{css}body{{background:#e9edf5}}.sheet{{width:1360px;padding:30px 36px}}h1{{font-size:26px;margin:0}}.panels{{display:grid;grid-template-columns:1fr 1fr;gap:18px;margin-top:20px}}.panel{{padding:22px;border:1px solid #dce2ed;border-radius:18px;background:white}}h2{{font-size:16px;margin:0 0 15px}}.icon-grid{{display:grid;grid-template-columns:repeat(4,1fr);gap:14px}}.icon-cell{{height:78px;border-radius:12px;background:#f4f6fa;display:flex;flex-direction:column;gap:9px;align-items:center;justify-content:center;color:#456bff}}.icon-cell>svg{{width:24px;height:24px}}.icon-cell b{{font-size:10px;font-weight:550;color:#536176}}.notes{{font-size:12px;line-height:1.9;color:#536176;margin:14px 0 0}}table{{border-collapse:collapse;width:100%;font-size:11px}}td{{padding:10px 0;border-bottom:1px solid #edf0f6}}td:nth-child(2){{width:90px;color:#456bff;font-weight:650}}td:nth-child(3){{color:#536176}}.example{{background:#f4f6fa;border-radius:12px;padding:14px}}.example .primary-actions{{margin:0}}.example .url{{margin-bottom:12px}}.example .filter{{margin:0}}.token-row{{display:flex;gap:18px;font-size:11px;color:#536176;margin-top:16px}}.token-row i{{display:inline-block;width:22px;height:22px;border-radius:7px;vertical-align:middle;margin-right:6px}}.motion-item{{padding:9px 0;font-size:12px;border-bottom:1px solid #edf0f6;display:flex;justify-content:space-between;gap:14px}}.motion-item b{{font-weight:650}}.motion-item span{{color:#536176}}.wide{{grid-column:span 2}}.diff{{display:flex;gap:22px}}.diff>div{{flex:1;font-size:12px;line-height:1.9;color:#536176}}.diff b{{color:#0f172a;font-size:13px}}.header-note{{font-size:12px;color:#536176;margin-top:5px}}</style><body><div class="sheet"><h1>提取页 · 图标 / 字体 / 动效</h1><div class="header-note">原生可实现规格；SVG 图标源文件已保存。尺寸 dp、文字 sp；中文使用已接入的 Noto Sans SC。</div><div class="panels"><section class="panel"><h2>01 / 统一线性图标</h2><div class="icon-grid">{icons}</div><p class="notes">24 × 24 统一网格，1.8 线宽、圆端点。主操作图标蓝色；蓝底按钮内为白色。图标触摸区至少 40 × 40，按钮触摸高 44。</p></section><section class="panel"><h2>02 / 字体与层级</h2><table>{tr}</table></section><section class="panel"><h2>03 / 操作与选中态</h2><div class="example"><div class="primary-actions"><button class="outline">{ico('open')}打开作品</button><button class="primary">{ico('scan')}扫描评论</button></div><div class="filter" style="margin-top:14px"><div class="indicator"></div><button class="active">全部 24</button><button>动图</button><button>图片</button></div></div><div class="token-row"><span><i style="background:#456bff"></i>主色</span><span><i style="background:#f4f6fa"></i>页面</span><span><i style="background:#dce2ed"></i>描边</span><span><i style="background:#0f172a"></i>正文</span></div><p class="notes">输入框直接描边，去掉多余外层大卡；操作按钮间距 10。链接输入、状态卡、网页操作和结果区左右对齐，页面边距 16。</p></section><section class="panel"><h2>04 / 与「页面动效」共享</h2><div class="motion-item"><b>分类切换</b><span>220 ms · 背景滑动＋结果轻移淡入</span></div><div class="motion-item"><b>按钮按压</b><span>100–120 ms · 0.96 缩放后回弹</span></div><div class="motion-item"><b>多选状态</b><span>150 ms · 勾选圆点淡入缩放</span></div><div class="motion-item"><b>网页展开</b><span>180 ms · 箭头旋转与高度过渡</span></div><div class="motion-item"><b>保存反馈</b><span>图标轻移；成功/失败沿用实际结果</span></div><p class="notes">关闭页面动效时取消装饰性过渡，立即切换。扫描条使用不确定进度，不根据素材数量推算百分比；预览动图保留原有播放逻辑。</p></section><section class="panel wide"><h2>05 / 对照当前截图的修正</h2><div class="diff"><div><b>布局</b><br>缩小链接外层留白，输入与操作拆成紧凑两行。扫描中展示标题、计数和明细。结果标题与多选同行，移除重复预览说明。</div><div><b>字号与颜色</b><br>网页操作由大号粗体收至 13 / 650；结果标题统一 18 / 750。打开作品改蓝色描边，分类改蓝底白字；次要文字采用 #536176。</div><div><b>图标与状态</b><br>链环、外链、扫描框、加载环、地球、下载均有独立源文件。展开箭头取消蓝色方块背景，GIF 改蓝色角标；置顶使用同线宽箭头。</div></div></section></div></div></body></html>'''
(p/'components.html').write_text(comp,encoding='utf8')
